<?php require_once __DIR__ . '/../includes/bootstrap.php';require_login('admin');$rows=database()->query('SELECT j.title,COUNT(qa.id) attempts,COALESCE(ROUND(AVG(qa.percentage),1),0) average_score,COALESCE(ROUND(AVG(qa.passed)*100,1),0) pass_rate FROM jobs j LEFT JOIN quiz_attempts qa ON qa.job_id=j.id GROUP BY j.id ORDER BY attempts DESC,j.title')->fetchAll();page_header('Quiz statistics');?><h1>Quiz statistics</h1><table><tr><th>Job</th><th>Attempts</th><th>Average score</th><th>Pass rate</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['title'])?></td><td><?=e($r['attempts'])?></td><td><?=e($r['average_score'])?>%</td><td><?=e($r['pass_rate'])?>%</td></tr><?php endforeach;?></table><?php page_footer(); ?>